Ltac rk_solve RK := unfold rkept in RK |- *; let x := fresh "x" in let Hx := fresh "Hx" in
  intros x Hx; cbn [In] in Hx; repeat (destruct Hx as [<-|Hx]; [csr; reflexivity|]); destruct Hx.

Lemma csc_refused : forall (sh : bool) (fr : bvmap 5 word) C Ar A m md regs (s pix1 w h cm datas : Z) (cv : cmapv) (ret : word) (S : TSet) (kR bR : Z)
    (fr1 : bvmap 5 word) (cs1 : bv 32) (A0 : AS) (m0 : word -> option byte) (vm0 : VmMaps) (r0 : bvmap 5 word) (kx bx : Z)
    (sel1 sel2 : Z) (sv1 sv2 : selv) (c1 c2 : Z -> Z -> Z),
  Cok C -> (s mod 16 = 0)%Z -> (c_top C - LSTK + CSC_STACK <= s)%Z -> (s <= c_top C)%Z -> ret_ok ret ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 4 = Z_to_bv 64 0x123d20 -> sub_live Ar A ->
  frm_zero cs1 -> (forall r : reg, In (u r) fs_list -> reg_get fr1 r = reg_get fr r) ->
  W C A0 m0 (with_vmmaps vm0 md) ->
  getr r0 2 = Z_to_bv 64 (s - 112) -> getr r0 8 = Z_to_bv 64 pix1 -> getr r0 9 = Z_to_bv 64 32 ->
  getr r0 18 = Z_to_bv 64 (hsz sh) -> getr r0 19 = Z_to_bv 64 (vsz sh) -> getr r0 10 = Z_to_bv 64 0 -> rkept regs r0 ->
  RST C Ar m s ret regs sh pix1 w h cm datas cv sel1 sel2 sv1 sv2 c1 c2 A0 m0 ->
  sels_static C A sh sel1 sel2 sv1 sv2 ->
  (forall q, sblk sel1 sv1 q \/ sblk sel2 sv2 q -> ~ tblk pix1 datas cm cv q) ->
  cslm (fun q => sblk sel1 sv1 q \/ sblk sel2 sv2 q) A A0 cm cv cm cv ->
  aroom A0 vm0 kx bx -> (kR - RK_csc (vsz sh) <= kx)%Z -> (bR - RB_csc (vsz sh) w h cm <= bx)%Z ->
  (0 <= kR - RK_csc (vsz sh))%Z -> (0 <= bR - RB_csc (vsz sh) w h cm)%Z ->
  csc_K fr C Ar A m md regs s pix1 (vsz sh) w h cm datas cv ret S kR bR ->
